-- Topaz: a slow-down whose missing frames are generated by a model, and the joined film upscaled.
--
-- shot_clip_conform.ai: slow with Topaz frame interpolation (generated frames) instead of ffmpeg's
--   motion-compensated interpolation.
-- film_render.upscaled_from_render_id / upscale_factor: a film render that is an upscaled copy of
--   another; null for a joined or uploaded film.
ALTER TABLE shot_clip_conform ADD COLUMN ai BOOLEAN NOT NULL DEFAULT false;
ALTER TABLE film_render ADD COLUMN upscaled_from_render_id UUID;
ALTER TABLE film_render ADD COLUMN upscale_factor NUMERIC(4, 2);
